 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("settings",0);dark=prefs.getBoolean("dark",false);hidden=prefs.getBoolean("hidden",false);String p=prefs.getString("path",home.getAbsolutePath());if(new File(p).isDirectory())dir=new File(p);String fs=prefs.getString("favorites","");if(!fs.isEmpty())favorites.addAll(Arrays.asList(fs.split("\n")));draw();}
